enum LeadStatus { New, Won, Lost }

sealed class Lead
{
    public LeadStatus Status { get; private set; }
    public decimal Value { get; private set; }
    public DateTime? ConvertedAtUtc { get; private set; }
    public int Events { get; private set; }
    private Lead() { }
    public static Lead Create(decimal v)
    {
        if (v <= 0) throw new InvalidOperationException("Giá trị phải > 0");
        return new Lead { Value = v, Status = LeadStatus.New };
    }
    public void Convert(DateTime utcNow)
    {
        if (Status == LeadStatus.Lost) throw new InvalidOperationException("mat");
        if (Status == LeadStatus.Won) return;
        Status = LeadStatus.Won;
        ConvertedAtUtc = utcNow;
        Events++;
    }
}

