#:package FluentValidation@11.*
using FluentValidation;

var v = new CreateLeadValidator();
var r1 = v.Validate(new Cmd("", "", null));
Console.WriteLine(r1.Errors.Count);
var r2 = v.Validate(new Cmd("An", "an@x.vn", ""));
Console.WriteLine(r2.IsValid);
var r3 = v.Validate(new Cmd("An", "an@x.vn", "123"));
Console.WriteLine(r3.Errors.Count);

record Cmd(string Name, string Email, string? Phone);
class CreateLeadValidator : AbstractValidator<Cmd>
{
    public CreateLeadValidator()
    {
        RuleLevelCascadeMode = CascadeMode.Stop;
        RuleFor(x => x.Name).NotEmpty().Length(2, 200);
        RuleFor(x => x.Email).NotEmpty().EmailAddress();
        RuleFor(x => x.Phone).Matches(@"^(0|\+84)[0-9]{9}$")
            .When(x => !string.IsNullOrEmpty(x.Phone));
    }
}

