#:package Microsoft.EntityFrameworkCore.Sqlite@10.0.0
#:property PublishAot=false
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

using var conn = new SqliteConnection("DataSource=:memory:");
conn.Open();
var opts = new DbContextOptionsBuilder<Db>().UseSqlite(conn).Options;
using var db = new Db(opts);
db.Database.EnsureCreated();
db.Leads.AddRange(new Lead { Id = 1 }, new Lead { Id = 2 });
db.SaveChanges();
db.Raised = 0;

var a = db.Leads.Find(1)!;
a.Convert();
db.SaveChanges();
Console.WriteLine($"{a.Status} events={db.Raised}");

db.Leads.Where(l => l.Id == 2).ExecuteUpdate(s => s.SetProperty(l => l.Status, "Won"));
var b = db.Leads.AsNoTracking().First(l => l.Id == 2);
Console.WriteLine($"{b.Status} events={db.Raised}");

class Lead
{
    public int Id { get; set; }
    public string Status { get; private set; } = "New";
    public int Pending { get; private set; }
    public void Convert() { Status = "Won"; Pending++; }
    public void Setter(string s) => Status = s;
    public void Clear() => Pending = 0;
}
class Db(DbContextOptions<Db> o) : DbContext(o)
{
    public DbSet<Lead> Leads => Set<Lead>();
    public int Raised;
    public override int SaveChanges()
    {
        foreach (var l in ChangeTracker.Entries<Lead>().Select(e => e.Entity).ToList()) { Raised += l.Pending; l.Clear(); }
        return base.SaveChanges();
    }
}
